+
+async function configDir(files: Record<string, string>): Promise<string> {
+  const dir = await Deno.makeTempDir();
+  await Promise.all(Object.entries(files).map(([name, value]) =>
+    Deno.writeTextFile(join(dir, name), value)
+  ));
+  return dir;
+}
+
+test("[command] - config - JSON values, precedence, and cache", async () => {
+  const dir = await configDir({
+    "app.json": JSON.stringify({ "dry-run": false, count: 0, tags: ["a", "b"], nested: { value: "ok" }, ignored: true }),
+  });
+  const command = new Command().throwErrors()
+    .config({ name: "app", searchPaths: [dir] })
+    .option("--dry-run", "...")
+    .option("--count <count:number>", "...")
+    .option("--tags <tag:string>", "...", { collect: true })
+    .option("--nested.value <value:string>", "...");
+  const result = await command.parse(["--count", "2"]);
+  assertEquals(result.options, { dryRun: false, count: 2, tags: ["a", "b"], nested: { value: "ok" } });
