+import { resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: Record<string, unknown>;
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const searchPaths = options.searchPaths ?? [Deno.cwd()];
+  const formats = options.formats ?? [".json", ".rc"];
+  const values: Record<string, unknown> = {};
+  let path: string | undefined;
+
+  for (const searchPath of searchPaths) {
+    for (const format of formats) {
+      const candidate = resolve(searchPath, fileName(options.name, format));
+      try {
+        const content = await Deno.readTextFile(candidate);
+        const parsed = parseConfig(content, candidate, format, options.parser);
+        if (!path) path = candidate;
+        // Earlier paths have precedence when merging.
+        for (const [key, value] of Object.entries(flatten(parsed))) {
+          if (!(key in values)) values[key] = value;
+        }
+        if (!options.mergeConfigs) return { path, values };
+        break;
+      } catch (error) {
+        if (error instanceof Deno.errors.NotFound) continue;
+        throw error;
+      }
+    }
+  }
+  return { path, values };
+}
+
+function fileName(name: string, format: string): string {
+  return format === ".rc" ? `.${name}rc` : `${name}${format}`;
+}
+
+function parseConfig(
+  content: string,
+  path: string,
+  format: string,
+  parser?: ConfigOptions["parser"],
+): Record<string, unknown> {
+  try {
+    const result = parser ? parser(content) : format === ".json"
+      ? JSON.parse(content)
+      : parseRc(content);
+    if (!isPlainObject(result)) {
+      throw new Error("expected an object");
+    }
+    return result;
+  } catch (error) {
+    if (error instanceof ConfigParseError) throw error;
+    throw new ConfigParseError(path, error instanceof Error ? error.message : String(error));
+  }
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const [index, line] of content.split(/\\r?\
/).entries()) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const separator = line.indexOf("=");
+    if (separator < 1) throw new Error(`invalid RC entry on line ${index + 1}`);
+    const key = line.slice(0, separator).trim();
+    let value = line.slice(separator + 1).trim();
+    if (!key) throw new Error(`invalid RC entry on line ${index + 1}`);
+    if (value.startsWith('"')) {
+      if (value.length < 2 || !value.endsWith('"')) {
+        throw new Error(`unterminated quoted value on line ${index + 1}`);
+      }
+      value = value.slice(1, -1);
+    }
+    result[key] = coerceRcValue(value);
+  }
+  return result;
+}
+
+function coerceRcValue(value: string): string | boolean | number {
+  if (value === "true") return true;
+  if (value === "false") return false;
+  if (/^-?(?:\\d+\\.?\\d*|\\.\\d+)(?:e[+-]?\\d+)?$/i.test(value)) {
+    return Number(value);
+  }
+  return value;
+}
+
+export function flatten(value: Record<string, unknown>): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const [key, child] of Object.entries(value)) {
+    const normalizedKey = camelCase(key);
+    if (isPlainObject(child)) {
+      for (const [nestedKey, nestedValue] of Object.entries(flatten(child))) {
+        result[`${normalizedKey}.${nestedKey}`] = nestedValue;
+      }
+    } else {
+      result[normalizedKey] = child;
+    }
+  }
+  return result;
+}
+
+export function camelCase(value: string): string {
+  return value.replace(/-([a-zA-Z0-9])/g, (_, letter) => letter.toUpperCase());
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value) &&
+    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
+}
