function expandDottedValues(
  values: Record<string, unknown>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(values)) {
    const parts = key.split(".");
    let target = result;
    for (const [index, part] of parts.entries()) {
      if (index === parts.length - 1) {
        target[part] = value;
      } else {
        target[part] ??= {};
        target = target[part] as Record<string, unknown>;
      }
    }
  }
  return result;
}

function deleteDottedValue(values: Record<string, unknown>, key: string): void {
  const parts = key.split(".");
  let target: Record<string, unknown> | undefined = values;
  for (const [index, part] of parts.entries()) {
    if (!target) return;
    if (index === parts.length - 1) delete target[part];
    else target = target[part] as Record<string, unknown> | undefined;
  }
}

